import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';import{execFileSync}from'node:child_process';import{hash,json}from'./bounded-source-hash-20261026.mjs';import{guarded}from'./run-small-native-task-guarded-20261025.mjs';
const specFile=process.argv[2];assert(specFile&&process.argv.length===3);const spec=json(specFile),s=json(spec.source.path),dir=spec.evidence;assert.equal(hash(spec.source.path),spec.source.sha256);assert(!fs.existsSync(dir));assert(spec.roots.length>0&&new Set(spec.roots).size===spec.roots.length);for(const p of spec.roots)assert(/^tests\/[A-Za-z0-9][A-Za-z0-9._-]*\.test\.(?:mjs|ts)$/.test(p)&&s.sourceRows.some(r=>r.path===p));function verify(){assert.equal(hash(specFile),specHash);assert.equal(hash(spec.source.path),spec.source.sha256);for(const r of s.sourceRows)assert.equal(hash(s.website+'/'+r.path),r.sha256,r.path);for(const d of s.dependencies){assert.equal(hash(d.file),d.sha256);assert.equal(hash(d.entry),d.entrySha256);}assert.equal(execFileSync('git',['-C',s.atlas,'rev-parse','HEAD'],{encoding:'utf8',windowsHide:true}).trim(),s.atlasHead);assert.equal(execFileSync('git',['-C',s.atlas,'status','--porcelain'],{encoding:'utf8',windowsHide:true}).trim(),'');}const specHash=hash(specFile);verify();const ix=json('CURRENT_CHECKPOINT.json');assert.deepEqual(ix.activeWork.current.activeExecutionSessions,[]);assert.equal(ix.activeWork.current.ownerPreviewPolicy.restartPermitted,false);ix.activeWork.current.activeExecutionSessions=[{kind:spec.kind,driverPid:process.pid,evidence:dir,sourceSha256:spec.source.sha256}];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(ix,null,2)+'\n');process.once('exit',code=>{if(code!==75||fs.existsSync(dir))return;const j=json('CURRENT_CHECKPOINT.json');if(j.activeWork.current.activeExecutionSessions[0]?.driverPid!==process.pid)return;const receipt=dir+'-ADMISSION_REFUSAL.json';fs.mkdirSync(path.dirname(receipt),{recursive:true});fs.writeFileSync(receipt,JSON.stringify({at:new Date().toISOString(),sourceSha256:spec.source.sha256,code,jobDirectoryAbsent:true,noProcessStarted:true},null,2)+'\n',{flag:'wx'});j.activeWork.current.activeExecutionSessions=[];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(j,null,2)+'\n');});
try{global.gc();const run=await guarded({site:s.website,dir,command:'--max-old-space-size=1024 --experimental-strip-types --test --test-reporter=tap --test-concurrency=1 '+spec.roots.join(' '),heap:1536,aggregate:3072,minimum:5120,extraEnv:{VM_ATLAS_SOURCE_REPO:s.atlas,ATLAS_SOURCE_REPO:s.atlas,VM_ATLAS_ACCESS_SQL_ROOT:s.website,VM_WEBSITE_ROOT:s.website}});assert.equal(hash(specFile),specHash);verify();const text=fs.readFileSync(dir+'/runner.stdout.log','utf8'),counts=Object.fromEntries(['tests','pass','fail','cancelled','skipped','todo'].map(k=>[k,Number([...text.matchAll(new RegExp('^# '+k+' (\\d+)','gm'))].at(-1)?.[1]??-1)]));const passing=run.passing&&counts.tests>=spec.minimumCases&&counts.tests===counts.pass&&counts.fail+counts.cancelled+counts.skipped+counts.todo===0;const result={at:new Date().toISOString(),source:spec.source,spec:{path:specFile,sha256:specHash},run,passing,counts,roots:spec.roots,wholeRootExecutionNoCaseFilters:true,allSourceAndNamedDependenciesStillExact:true,fullWebsiteTypes:false,stockWebsiteBuild:false,wholeStockSuitePassing:false,normalPreviewChanged:false,clinicalApproval:false};fs.writeFileSync(dir+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({path:dir+'/RESULT.json',sha256:hash(dir+'/RESULT.json'),passing,counts,roots:spec.roots.length}));process.exitCode=passing?0:1;}finally{const j=json('CURRENT_CHECKPOINT.json');assert.equal(j.activeWork.current.activeExecutionSessions[0]?.driverPid,process.pid);j.activeWork.current.activeExecutionSessions=[];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(j,null,2)+'\n');}
